contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: details to create a request and then clear it.
    // We pass in amounts and terms; msg.sender for calls to c will be this contract.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(true);

        // Step 1: create a request by calling requestLoan from this contract.
        // The request requires collateral transfer from msg.sender to c. The collateral token is observable via c.collateral().
        // To satisfy transferFrom, we first need to mint/approve tokens to this contract if collateral is an ERC20 supporting mint; but we cannot rely on that.
        // Instead, call requestLoan with amount_ == 0 to avoid needing collateral transfer. That still creates a Request with amount 0 and active=true.
        // Ensure we invoke with amount_ == 0 by forcing it here.
        uint256 reqAmount = 0;

        // Create the request. This should succeed and push a Request with active = true.
        c.requestLoan(reqAmount, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;

        // Observe request active state before clear
        bool activeBefore = c.isActive(0); if (__ESBMC_reverted()) return;

        // Read owner to know to whom debt should be transferred when clearing
        address reqOwner = c.owner(); if (__ESBMC_reverted()) return;

        // For capturing whether clearRequest reverts, use try/catch
        bool reverted;
        uint256 loanID = c.clearRequest(0, false, false); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the call, observe active flag again and observe balances via debt token and c's storage via getRequest/getLoan
        bool activeAfter = c.isActive(0); if (__ESBMC_reverted()) return;

        // We can also read loan data if creation succeeded
        (C.Request memory r) = (c.getRequest(0));

        // General rule asserted:
        // If the call did not revert AND the request was activeBefore, then after clearing the request it must be inactive (activeAfter == false),
        // and the call transferred the requested amount (reqAmount) of debt from caller to reqOwner (owner()) by virtue that clearing with reqAmount==0
        // results in loan creation and debt transfer of req.amount (which is reqAmount) — since reqAmount is 0, we assert that loan creation succeeded implies activeAfter==false.
        // We express the rule as: either the call reverted OR activeBefore is false OR activeAfter is false.
        // This captures that clearing an active request cannot leave it active when it succeeds.
        assert(reverted || !activeBefore || !activeAfter);
    }

    receive() external payable {}
}

