pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) internal {
        vm.assume(true);
        uint256 reqAmount = 0;
        try c.requestLoan(reqAmount, interest_, loanToCollateral_, duration_) {} catch { return; }
        bool activeBefore;
        try c.isActive(0) returns (bool __r) { activeBefore = __r; } catch { return; }
        address reqOwner;
        try c.owner() returns (address __r) { reqOwner = __r; } catch { return; }
        bool reverted;
        try c.clearRequest(0, false, false) returns (uint256 loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool activeAfter;
        try c.isActive(0) returns (bool __r) { activeAfter = __r; } catch { return; }
        (Cooler.Request memory r) = (c.getRequest(0));
        assertTrue(reverted || !activeBefore || !activeAfter);
    }

    function testFuzz_run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        _run(amount_, interest_, loanToCollateral_, duration_);
    }

    receive() external payable {}
}
